use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::{DslValue,ValueRefusalKind,shared_issuance::SealedShared,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneSource,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(crate::RetireOwned)]#[value(crate="crate")]struct Row{id:SealedShared<String>,name:SealedShared<String>,value:i64}
struct Receiving{binding:Option<RetainedCloneBinding>,fields:[NativeIntrinsicSharedField<String>;2],positions:[Option<usize>;2],id:ManuallyDrop<Option<SealedShared<String>>>,name:ManuallyDrop<Option<SealedShared<String>>>,output:ManuallyDrop<Option<Row>>,retirement:RetainedCloneClose,value:Option<i64>,index:usize,phase:u8,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native row requires exactly one id, name and integer value from its original source")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl NativeReceive<DslValue> for Row{
 type Receiver=Receiving;
 fn receive_birth_demand()->RetirementDemand{fixed(size_of::<Receiving>())}
 fn begin_receive(g:RetainedCloneGrant)->Result<(Receiving,RetainedCloneProgress),ValueError>{let d=Self::receive_birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid());}Ok((Receiving{binding:None,fields:Default::default(),positions:[None;2],id:ManuallyDrop::new(None),name:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),value:None,index:0,phase:0,closing:false},receipt(d)))}
}
impl Receiving{
 fn field<'a>(&self,original:RetainedCloneRef<'a,DslValue>,field:usize)->Result<RetainedCloneRef<'a,String>,ValueError>{let index=self.positions[field].ok_or_else(invalid)?;Ok(original.project(index,move|value|{let DslValue::Object(entries)=value else{unreachable!()};let DslValue::String(value)=&entries[index].1 else{unreachable!()};value}))}
}
impl NativeReceiver<DslValue,Row> for Receiving{
 fn demands(&self,original:RetainedCloneRef<'_,DslValue>,body:usize)->Result<RetirementDemand,ValueError>{
  if self.closing||self.phase>=7{return Err(invalid());}original.check_binding(&self.binding)?;
  match self.phase{0=>Ok(fixed(original.binding_copy_bytes()+size_of::<u8>())),1=>Ok(fixed(5+3*size_of::<usize>()+size_of::<Option<i64>>()+size_of::<u8>())),2|3=>{let mut d=self.fields[usize::from(self.phase-2)].demands(self.field(original,usize::from(self.phase-2))?,body)?;d.copy_bytes+=size_of::<u8>();Ok(d)},4|5=>{let mut d=self.fields[usize::from(self.phase-4)].take_demand()?;d.copy_bytes+=size_of::<SealedShared<String>>()+size_of::<u8>();Ok(d)},6=>Ok(fixed(3*size_of::<Row>()+size_of::<u8>())),_=>Err(invalid())}
 }
 fn advance(&mut self,original:RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
  let d=self.demands(original,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}control.checkpoint()?;
  match self.phase{
   0=>{let p=original.bind(&mut self.binding,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<u8>(),..g})?.ok_or_else(invalid)?;self.phase=1;let mut p=p;p.copied_bytes+=size_of::<u8>();return Ok(RetainedCloneStep::Progress(p));},
   1=>{let DslValue::Object(entries)=original.get()else{return Err(invalid());};if entries.len()!=3{return Err(invalid());}let(key,value)=entries.get(self.index).ok_or_else(invalid)?;match(key.as_str(),value){("id",DslValue::String(_))if self.positions[0].is_none()=>self.positions[0]=Some(self.index),("name",DslValue::String(_))if self.positions[1].is_none()=>self.positions[1]=Some(self.index),("value",DslValue::Number(value))if self.value.is_none()=>self.value=Some(value.as_i64().ok_or_else(invalid)?),_=>return Err(invalid())};self.index+=1;if self.index==3{self.phase=2;}},
   2|3=>{let field=usize::from(self.phase-2);if self.fields[field].ready(){return Err(invalid());}let original=self.field(original,field)?;let mut p=self.fields[field].advance(original,control,body,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<u8>(),..g})?.progress();if self.fields[field].ready(){self.phase+=1;}p.copied_bytes+=size_of::<u8>();return Ok(RetainedCloneStep::Progress(p));},
   4|5=>{let field=usize::from(self.phase-4);let overhead=size_of::<SealedShared<String>>()+size_of::<u8>();let(value,mut p)=self.fields[field].take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-overhead,..g})?.ok_or_else(invalid)?;if field==0{*self.id=Some(value);}else{*self.name=Some(value);}self.phase+=1;p.copied_bytes+=overhead;return Ok(RetainedCloneStep::Progress(p));},
   6=>{*self.output=Some(Row{id:self.id.take().ok_or_else(invalid)?,name:self.name.take().ok_or_else(invalid)?,value:self.value.ok_or_else(invalid)?});self.phase=7;},_=>return Err(invalid())
  }Ok(if self.phase==7{RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})
 }
 fn output_ready(&self)->bool{!self.closing&&self.phase==7&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(fixed(2*size_of::<Row>()+size_of::<u8>()))}
 fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(Row,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}self.phase=8;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))}
 fn begin_close(&mut self){self.closing=true;for field in &mut self.fields{field.begin_close();}}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{
  if !self.closing{return Err(invalid());}for field in &self.fields{if !field.terminal_is_empty(){return field.close_demands(body);}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Row>(false,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<Row>(true,&None,body);}if self.id.is_some()||self.name.is_some(){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body);}RetainedCloneBinding::close_demand(&self.binding,body)
 }
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
  let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}for field in &mut self.fields{if !field.terminal_is_empty(){return field.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.id,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.name,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}RetainedCloneBinding::close_one(&mut self.binding,g)
 }
 fn terminal_is_empty(&self)->bool{self.fields.iter().all(NativeIntrinsicSharedField::terminal_is_empty)&&self.id.is_none()&&self.name.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for Receiving{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native receiving retains original physical owner");}}
fn funded(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn drain<T:RetireOwned>(value:T){let mut o=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native fixture supports original closure"));for _ in 0..10000{if o.terminal_is_empty(){return;}let g=funded(o.next_demand(4096).unwrap());assert!(o.step(g).unwrap().progress().fits(g));}panic!("native receiving cleanup stalled");}
fn source(value:DslValue)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),..funded(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).unwrap_or_else(|_|panic!("original input source admission")).0}
fn input()->DslValue{let json:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();DslValue::Object(vec![("id".into(),DslValue::String(json["before"]["id"].as_str().unwrap().into())),("name".into(),DslValue::String(json["before"]["name"].as_str().unwrap().into())),("value".into(),DslValue::Number(crate::Number::Int(json["before"]["value"].as_i64().unwrap())))])}
#[test]
fn native_receive_original_row_has_funded_fields_and_every_cancellation_frontier(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut observed=0;
 for cut in 0..128{let original=source(input());let foreign=source(input());let birth=Row::receive_birth_demand();let(mut receiver,_)=Row::begin_receive(funded(birth)).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;
  while turns<cut&&!receiver.output_ready(){let d=receiver.demands(original.borrow(),4096).unwrap();let g=funded(d);if turns>0{assert!(receiver.demands(foreign.borrow(),4096).is_err());}for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue};let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,denied)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(original.borrow(),4096).unwrap(),d);}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,g)).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;}
  if receiver.output_ready(){observed=turns;let g=funded(receiver.take_demand().unwrap());let(row,p)=receiver.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());drain(row);}
  receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break;}let g=funded(receiver.close_demands(4096).unwrap());let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(receiver.terminal_is_empty());drain(original);drain(foreign);if observed>0&&cut>observed{break;}
 }assert!(observed>0);
}

fn close_receiver(receiver:&mut Receiving){receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){return;}let g=funded(receiver.close_demands(4096).unwrap());assert!(receiver.close_step(g).unwrap().progress().fits(g));}panic!("refused receiving owner did not close");}
#[test]
fn native_receive_constructor_and_output_denials_preserve_exact_owner(){
 let d=Row::receive_birth_demand();let g=funded(d);for axis in 0..3{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||Row::begin_receive(denied));assert!(result.is_err());assert_eq!(heap,(0,0));}
 let original=source(input());let(mut receiver,_)=Row::begin_receive(g).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;for _ in 0..1000{if receiver.output_ready(){break;}let g=funded(receiver.demands(original.borrow(),4096).unwrap());control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,g)).unwrap();}assert!(receiver.output_ready());let pointer=receiver.output.as_ref().unwrap().id.get().as_ptr();let d=receiver.take_demand().unwrap();let g=funded(d);for axis in 0..3{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.take(denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert!(receiver.output_ready());assert_eq!(receiver.output.as_ref().unwrap().id.get().as_ptr(),pointer);}let(row,p)=receiver.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(row.id.get().as_ptr(),pointer);drain(row);close_receiver(&mut receiver);drain(original);
}
#[test]
fn native_receive_domain_and_original_callback_refusals_keep_all_partial_custody(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let entries=law["refusedEntries"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),if let Some(value)=pair[1].as_str(){DslValue::String(value.to_owned())}else{DslValue::Number(crate::Number::Int(pair[1].as_i64().unwrap()))})).collect();let original=source(DslValue::Object(entries));let(mut receiver,_)=Row::begin_receive(funded(Row::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut refused=false;for _ in 0..16{let g=funded(receiver.demands(original.borrow(),4096).unwrap());if control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,g)).is_err(){refused=true;break;}}assert!(refused);assert!(!receiver.output_ready());let DslValue::Object(entries)=original.borrow().get()else{panic!("original object changed")};assert_eq!(entries[0].0,entries[1].0);close_receiver(&mut receiver);drain(original);
 let original=source(input());let(mut receiver,_)=Row::begin_receive(funded(Row::receive_birth_demand())).unwrap();let admitted=std::cell::Cell::new(true);let mut callback=|_|admitted.get();let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;for _ in 0..1000{if receiver.phase==3{break;}let g=funded(receiver.demands(original.borrow(),4096).unwrap());control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,g)).unwrap();}assert_eq!(receiver.phase,3);assert!(receiver.fields[0].ready());admitted.set(false);let g=funded(receiver.demands(original.borrow(),4096).unwrap());let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,4096,g)));assert!(result.is_err());assert_eq!(heap,(0,0));assert!(receiver.fields[0].ready());assert!(!receiver.output_ready());close_receiver(&mut receiver);drain(original);
}
